### FileValidation Struct Enhancement
```rust
pub struct FileValidation {
    pub file: PathBuf,
    pub errors: Vec<String>,
    pub warnings: Vec<String>,
}

impl FileValidation {
    fn validate_path_exists(&mut self, key: &str, path: &Path) {
        if \!path.exists() {
            self.errors.push(format\!("{}: path does not exist: {}", key, path.display()));
        }
    }

    fn validate_path_writable(&mut self, key: &str, path: &Path) {
        // Check parent directory is writable
    }

    fn validate_ssh_key_permissions(&mut self, key: &str, path: &Path) {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            if let Ok(meta) = path.metadata() {
                let mode = meta.permissions().mode() & 0o777;
                if mode \!= 0o600 && mode \!= 0o400 {
                    self.warnings.push(format\!(
                        "{}: SSH key has insecure permissions {:o} (should be 600)",
                        key, mode
                    ));
                }
            }
        }
    }

    fn validate_glob_pattern(&mut self, key: &str, pattern: &str) {
        if glob::Pattern::new(pattern).is_err() {
            self.errors.push(format\!("{}: invalid glob pattern: {}", key, pattern));
        }
    }
}
```

