const REMOTE_RCH_PATH: &str = "~/.local/bin/rch-wkr";

// Before (stub):
rustup_ok: true,          // HARDCODED
current_version: None,    // NEVER POPULATED

// After (real):
let (rustup_ok, current_version) = if ssh_ok {
    // Check rustup availability
    let rustup_result = ssh_executor.run_command("command -v rustup").await;
    let rustup_ok = rustup_result.as_ref().map(|o| o.exit_code == 0).unwrap_or(false);

    if \!rustup_ok {
        tracing::warn\!(worker = %worker.id, "rustup not found");
        issues.push(PreflightIssue {
            severity: Severity::Warning,  // Warning, not Error - not all workers need Rust
            check: "rustup".to_string(),
            message: "rustup is not installed or not in PATH".to_string(),
            remediation: Some(
                "Install rustup: curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh".to_string()
            ),
        });
    } else {
        tracing::debug\!(worker = %worker.id, "rustup found");

        // Optionally check Rust version
        if let Ok(output) = ssh_executor.run_command("rustc --version").await {
            tracing::debug\!(worker = %worker.id, rust_version = %output.stdout.trim(), "Rust version");
        }
    }

    // Detect current rch-wkr version if installed
    // NOTE: Using hardcoded path since WorkerConfig doesn't have rch_wkr_path
    let current_version = ssh_executor
        .run_command(&format\!("{} --version 2>/dev/null", REMOTE_RCH_PATH))
        .await
        .ok()
        .and_then(|output| {
            if output.exit_code == 0 {
                // Parse "rch-wkr 1.0.0" -> "1.0.0"
                output.stdout.trim()
                    .split_whitespace()
                    .nth(1)
                    .map(String::from)
            } else {
                None
            }
        });

    match &current_version {
        Some(v) => tracing::info\!(worker = %worker.id, version = %v, "rch-wkr version detected"),
        None => tracing::debug\!(worker = %worker.id, "rch-wkr not installed or version not detected"),
    }

    (rustup_ok, current_version)
} else {
    // SSH failed, can't check
    (false, None)
};
