#[tokio::test]
async fn test_fleet_status_respects_concurrency_limit() {
    use std::sync::atomic::{AtomicUsize, Ordering};

    let workers: Vec<_> = (0..50).map(|i| mock_worker(&format!("worker{}", i))).collect();
    let concurrent_count = Arc::new(AtomicUsize::new(0));
    let max_concurrent = Arc::new(AtomicUsize::new(0));

    let mock = MockSshExecutor::with_concurrency_tracking(
        concurrent_count.clone(),
        max_concurrent.clone()
    );

    get_fleet_status_with_executor(&workers, mock, DEFAULT_TIMEOUT).await.unwrap();

    // Should never exceed MAX_CONCURRENT_QUERIES (10)
    assert!(max_concurrent.load(Ordering::SeqCst) <= MAX_CONCURRENT_QUERIES,
        "Exceeded concurrency limit: {} > {}",
        max_concurrent.load(Ordering::SeqCst),
        MAX_CONCURRENT_QUERIES
    );
}
