## Task
Implement actual disk space checking on remote worker.

**IMPORTANT: WorkerConfig does NOT have an `os` field. Use a portable df command.**

## What to Implement
Replace hardcoded disk values with real df command:

```rust
const MIN_DISK_SPACE_MB: u64 = 500;

// Before (stub):
disk_space_mb: 10000,
disk_ok: true,

// After (real):
let (disk_space_mb, disk_ok) = if ssh_ok {
    // Only check disk if SSH succeeded
    // Use portable command that works on both Linux and macOS
    let disk_cmd = "df -Pm /tmp 2>/dev/null | tail -1 | awk '{print $4}'";

    match ssh_executor.run_command(disk_cmd).await {
        Ok(output) => {
            match output.stdout.trim().parse::<u64>() {
                Ok(mb) => {
                    let ok = mb >= MIN_DISK_SPACE_MB;
                    if \!ok {
                        issues.push(PreflightIssue {
                            severity: Severity::Warning,
                            check: "disk_space".to_string(),
                            message: format\!(
                                "Low disk space: {}MB available, {}MB required",
                                mb, MIN_DISK_SPACE_MB
                            ),
                            remediation: Some(format\!(
                                "Free up disk space on {}: rm -rf /tmp/rch-* or expand volume",
                                worker.host
                            )),
                        });
                    }
                    tracing::info\!(worker = %worker.id, disk_mb = %mb, ok = %ok, "Disk space check complete");
                    (mb, ok)
                }
                Err(e) => {
                    tracing::warn\!(worker = %worker.id, error = %e, raw = %output.stdout, "Failed to parse disk space output");
                    issues.push(PreflightIssue {
                        severity: Severity::Warning,
                        check: "disk_space".to_string(),
                        message: format\!("Could not parse disk space: {}", e),
                        remediation: None,
                    });
                    (0, false)
                }
            }
        }
        Err(e) => {
            tracing::warn\!(worker = %worker.id, error = %e, "Disk space check failed");
            issues.push(PreflightIssue {
                severity: Severity::Warning,
                check: "disk_space".to_string(),
                message: format\!("Disk space check failed: {}", e),
                remediation: None,
            });
            (0, false)
        }
    }
} else {
    // SSH failed, can't check disk
    (0, false)
};
```

## Cross-Platform Support
```rust
// The command "df -Pm /tmp | tail -1 | awk '{print $4}'" is POSIX-portable:
// -P: POSIX output format (consistent columns)
// -m: 1MB blocks (works on Linux and macOS)
// awk '{print $4}': extract available space (4th column)

// Fallback command if -Pm not supported:
fn disk_space_command() -> &'static str {
    "df -Pm /tmp 2>/dev/null | tail -1 | awk '{print $4}' || "     "df -m /tmp 2>/dev/null | tail -1 | awk '{print $4}'"
}
```

## Technical Details
- Query /tmp or worker's configured work directory
- Parse output as u64 megabytes
- MIN_DISK_SPACE_MB = 500 (defined constant)
- Use portable df command (no OS detection needed)
- Skip check if SSH failed (can't run remote command)

## Logging Requirements
```rust
tracing::debug\!(worker = %worker.id, "Checking disk space");
tracing::info\!(worker = %worker.id, disk_mb = %mb, threshold = %MIN_DISK_SPACE_MB, "Disk space: {} MB (min: {} MB)", mb, MIN_DISK_SPACE_MB);
tracing::warn\!(worker = %worker.id, disk_mb = %mb, "Low disk space warning");
tracing::warn\!(worker = %worker.id, error = %e, raw = %output, "Failed to parse disk space output");
```

