## Implementation
```rust
async fn cancel_builds(all: bool, build_id: Option<u64>, dry_run: bool) -> Result<()> {
    let builds = if all {
        get_all_active_builds().await?
    } else {
        vec\![get_build(build_id.unwrap()).await?]
    };

    if dry_run {
        println\!("Would cancel {} builds:", builds.len());
        for build in &builds {
            println\!("  {}  {}  [worker: {}, {}]",
                build.id, build.command, build.worker, build.elapsed);
        }
        println\!("\nRun without --dry-run to cancel.");
        return Ok(());
    }

    // Actual cancellation
}
```

