#[tokio::test]
async fn test_remote_compilation_workflow() {
    let harness = TestHarness::new("remote_compilation").await;
    harness.require_workers(&["css"]).await;  // Ensure at least one worker

    // Start daemon
    harness.start_daemon(&[]).await.unwrap();

    // Enable RCH for compilation
    harness.set_env("RCH_ENABLED", "1");

    // Compile via RCH
    let result = harness.run_command("cargo build --release -p rch").await.unwrap();

    // Verify compilation happened on worker
    let logs = harness.get_daemon_logs().await;
    assert!(logs.contains("dispatched to worker"));
    assert!(logs.contains("css") || logs.contains("csd"));  // One of our workers

    // Verify binary exists locally
    let binary_path = harness.project_root().join("target/release/rch");
    assert!(binary_path.exists());

    harness.cleanup().await;
}
```

