```rust
#[tokio::test]
async fn test_verify_compilation_on_worker() {
    let harness = TestHarness::new("worker_verification").await;
    let worker = harness.require_workers(&["css"]).await[0].clone();

    // Start daemon and compile
    harness.start_daemon(&[]).await.unwrap();
    harness.set_env("RCH_ENABLED", "1");
    harness.run_command("cargo build --release -p rch").await.unwrap();

    // SSH to worker and verify work directory exists
    let ssh_result = harness.ssh_to_worker(&worker, "ls -la ~/.rch/work/").await.unwrap();
    assert!(ssh_result.stdout.contains("rch"));  // Project directory exists

    // Verify object files were created on worker
    let obj_result = harness.ssh_to_worker(&worker, "find ~/.rch/work -name '*.o' | head -5").await.unwrap();
    assert!(!obj_result.stdout.is_empty());  // Object files exist

    harness.cleanup().await;
}
```

### 5. Binary Transfer Verification E2E
```rust
#[tokio::test]
async fn test_binary_transfer_from_worker() {
    let harness = TestHarness::new("binary_transfer").await;
    let worker = harness.require_workers(&["css"]).await[0].clone();

    // Get initial state
    let binary_path = harness.project_root().join("target/release/rch");
    let _ = fs::remove_file(&binary_path).await;  // Remove if exists

    // Compile via RCH
    harness.start_daemon(&[]).await.unwrap();
    harness.set_env("RCH_ENABLED", "1");
    harness.run_command("cargo build --release -p rch").await.unwrap();

    // Binary should exist locally now
    assert!(binary_path.exists());

    // Get hash from local binary
    let local_hash = compute_sha256(&binary_path).await.unwrap();

    // Get hash from worker's compiled binary
    let remote_hash_cmd = format!(
        "sha256sum ~/.rch/work/*/target/release/rch | cut -d' ' -f1"
    );
    let remote_result = harness.ssh_to_worker(&worker, &remote_hash_cmd).await.unwrap();
    let remote_hash = remote_result.stdout.trim();

    // Hashes should match (binary transferred correctly)
    assert_eq!(local_hash, remote_hash);

    harness.cleanup().await;
}
```

### 6. Complete Self-Test Workflow E2E
```rust
#[tokio::test]
async fn test_complete_self_test_workflow() {
    let harness = TestHarness::new("complete_self_test").await;
    harness.require_workers(&["css"]).await;

    // Step 1: Compute initial hash
    harness.run_local_build("cargo build --release -p rch").await.unwrap();
    let initial_hash = compute_binary_hash(&harness, "rch").await;
    log::info!("Initial binary hash: {}", initial_hash);

    // Step 2: Make a code change
    let change_marker = format!("// Self-test marker: {}", Uuid::new_v4());
    harness.inject_code_change("rch/src/main.rs", &change_marker).await;
    log::info!("Injected code change");

    // Step 3: Start daemon and get telemetry baseline
    harness.start_daemon(&[]).await.unwrap();
    let worker = harness.get_assigned_worker().await.unwrap();
    let baseline_cpu = harness.get_worker_cpu(&worker).await.unwrap();
    log::info!("Worker {} baseline CPU: {:.1}%", worker, baseline_cpu);

    // Step 4: Compile via RCH
    harness.set_env("RCH_ENABLED", "1");
    let start = Instant::now();
    harness.run_command("cargo build --release -p rch").await.unwrap();
    let compile_duration = start.elapsed();
    log::info!("Compilation took: {:?}", compile_duration);

    // Step 5: Verify compilation on worker (via SSH)
    let ssh_check = harness.ssh_to_worker(&worker, "pgrep -f 'rustc.*rch'").await;
    // Note: process may have finished, but logs should show it ran
    let logs = harness.get_daemon_logs().await;
    assert!(logs.contains(&format!("dispatched to {}", worker)));

    // Step 6: Get CPU during compilation (from telemetry history)
    let peak_cpu = harness.get_worker_peak_cpu(&worker, compile_duration).await.unwrap();
    log::info!("Worker {} peak CPU during compilation: {:.1}%", worker, peak_cpu);
    assert!(peak_cpu > baseline_cpu);  // CPU should have increased

    // Step 7: Verify binary transferred and hash differs
    let new_hash = compute_binary_hash(&harness, "rch").await;
    log::info!("New binary hash: {}", new_hash);
    assert_ne!(initial_hash, new_hash);

    // Step 8: Verify local hash matches worker hash
    let remote_hash = harness.get_worker_binary_hash(&worker, "rch").await.unwrap();
    assert_eq!(new_hash, remote_hash);
    log::info!("Hash verification passed: local matches remote");

    // Cleanup: revert code change
    harness.revert_code_change("rch/src/main.rs").await;
    harness.cleanup().await;
}
```

