use blake3::Hasher;

/// Identifying fingerprint for a Bun/Node project's dependency manifest.
/// `bun install` is run iff this hash changes since the last successful install.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DependencyFingerprint {
    /// blake3 of the concatenation of (package.json, bun.lockb if exists, package-lock.json if exists, pnpm-lock.yaml if exists)
    pub hash: String,
    /// Source files included in the hash (for diagnostic logging)
    pub sources: Vec<String>,
}

#[derive(Debug, Serialize, Deserialize, JsonSchema)]
pub struct PrepareReport {
    pub runtime: RequiredRuntime,
    pub action: PrepareAction,        // Skipped (cache valid) | Installed | Failed
    pub fingerprint: Option<DependencyFingerprint>,
    pub fingerprint_changed_from: Option<String>,    // previous hash, for diagnostics
    pub install_log_path: Option<PathBuf>,
    pub took_ms: u64,
    pub bytes_added_to_node_modules: u64,
}

/// Compute the fingerprint without doing any IO beyond reading manifest files.
pub async fn compute_fingerprint(project_root: &Path) -> Result<DependencyFingerprint> {
    let mut hasher = Hasher::new();
    let mut sources = Vec::new();
    for name in ["package.json", "bun.lockb", "package-lock.json", "pnpm-lock.yaml", "yarn.lock", "bunfig.toml"] {
        let p = project_root.join(name);
        if p.exists() {
            let bytes = tokio::fs::read(&p).await.with_context(|| format!("read {}", p.display()))?;
            hasher.update(name.as_bytes());      // include filename so we can detect a switch from yarn->pnpm
            hasher.update(&bytes);
            sources.push(name.to_string());
        }
    }
    if sources.is_empty() {
        bail!("no package manifest found in {}", project_root.display());
    }
    Ok(DependencyFingerprint {
        hash: hasher.finalize().to_hex().to_string(),
        sources,
    })
}

/// Decide what to install based on which package manager is in use.
fn detect_package_manager(project_root: &Path) -> PackageManager {
    if project_root.join("bun.lockb").exists() { return PackageManager::Bun; }
    if project_root.join("pnpm-lock.yaml").exists() { return PackageManager::Pnpm; }
    if project_root.join("yarn.lock").exists() { return PackageManager::Yarn; }
    PackageManager::Npm
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
pub enum PackageManager { Bun, Pnpm, Yarn, Npm }

impl PackageManager {
    pub fn install_command(&self, project_root: &Path) -> Vec<String> {
        match self {
            Self::Bun  => vec!["bun".into(), "install".into(), "--frozen-lockfile".into()],
            Self::Pnpm => vec!["pnpm".into(), "install".into(), "--frozen-lockfile".into()],
            Self::Yarn => vec!["yarn".into(), "install".into(), "--frozen-lockfile".into()],
            Self::Npm  => vec!["npm".into(), "ci".into()],
        }
    }
}

/// Look up the previously-installed fingerprint stored alongside the project's
/// node_modules directory on the worker.
async fn read_cached_fingerprint(project_root: &Path) -> Option<DependencyFingerprint> {
    let path = project_root.join(".rch_dep_fingerprint.json");
    let bytes = tokio::fs::read(&path).await.ok()?;
    serde_json::from_slice(&bytes).ok()
}

async fn write_cached_fingerprint(project_root: &Path, fp: &DependencyFingerprint) -> Result<()> {
    let path = project_root.join(".rch_dep_fingerprint.json");
    let bytes = serde_json::to_vec(fp)?;
    tokio::fs::write(&path, bytes).await.context("write fingerprint")?;
    Ok(())
}

/// Top-level prepare entry point. Idempotent: a re-run with unchanged fingerprint is a no-op.
pub async fn prepare(
    project_root: &Path,
    runtime: RequiredRuntime,
    log_dir: &Path,
) -> Result<PrepareReport> {
    let started = std::time::Instant::now();
    match runtime {
        RequiredRuntime::Bun | RequiredRuntime::Node => {
            prepare_node_like(project_root, runtime, log_dir, started).await
        }
        RequiredRuntime::Rust | RequiredRuntime::CCpp | RequiredRuntime::Other(_) => {
            // No-op for non-Node ecosystems
            Ok(PrepareReport {
                runtime,
                action: PrepareAction::Skipped,
                fingerprint: None,
                fingerprint_changed_from: None,
                install_log_path: None,
                took_ms: started.elapsed().as_millis() as u64,
                bytes_added_to_node_modules: 0,
            })
        }
    }
}

async fn prepare_node_like(
    project_root: &Path,
    runtime: RequiredRuntime,
    log_dir: &Path,
    started: std::time::Instant,
) -> Result<PrepareReport> {
    let fingerprint = compute_fingerprint(project_root).await?;
    let cached = read_cached_fingerprint(project_root).await;

    // Cache hit: skip install
    if let Some(prev) = &cached {
        if prev.hash == fingerprint.hash && project_root.join("node_modules").exists() {
            tracing::info!(
                target: "rch::wkr::prepare",
                action = "cache_hit",
                hash = %fingerprint.hash,
                "node_modules cached, skipping install"
            );
            return Ok(PrepareReport {
                runtime,
                action: PrepareAction::Skipped,
                fingerprint: Some(fingerprint),
                fingerprint_changed_from: None,
                install_log_path: None,
                took_ms: started.elapsed().as_millis() as u64,
                bytes_added_to_node_modules: 0,
            });
        }
    }

    // Cache miss: install
    let pm = detect_package_manager(project_root);
    let cmd = pm.install_command(project_root);
    let log_path = log_dir.join(format!("prepare_{}.log", fingerprint.hash));
    let log_file = std::fs::File::create(&log_path)?;

    tracing::info!(
        target: "rch::wkr::prepare",
        action = "installing",
        manager = ?pm,
        hash = %fingerprint.hash,
        prev_hash = ?cached.as_ref().map(|c| &c.hash),
        "running pre-execution install"
    );

    let pre_size = dir_size(&project_root.join("node_modules")).await.unwrap_or(0);

    let status = Command::new(&cmd[0])
        .args(&cmd[1..])
        .current_dir(project_root)
        .stdout(log_file.try_clone()?)
        .stderr(log_file)
        .status()
        .await
        .with_context(|| format!("spawn {:?}", cmd))?;

    if !status.success() {
        return Ok(PrepareReport {
            runtime,
            action: PrepareAction::Failed,
            fingerprint: Some(fingerprint),
            fingerprint_changed_from: cached.map(|c| c.hash),
            install_log_path: Some(log_path),
            took_ms: started.elapsed().as_millis() as u64,
            bytes_added_to_node_modules: 0,
        });
    }

    let post_size = dir_size(&project_root.join("node_modules")).await.unwrap_or(0);
    write_cached_fingerprint(project_root, &fingerprint).await?;

    Ok(PrepareReport {
        runtime,
        action: PrepareAction::Installed,
        fingerprint: Some(fingerprint.clone()),
        fingerprint_changed_from: cached.map(|c| c.hash),
        install_log_path: Some(log_path),
        took_ms: started.elapsed().as_millis() as u64,
        bytes_added_to_node_modules: post_size.saturating_sub(pre_size),
    })
}
```

### 2. Wire into `rch-wkr/src/executor.rs`

Before executing a `bun test` / `bun typecheck` / `npm test` / etc., call `prepare::prepare(project_root, RequiredRuntime::Bun, log_dir)`. If `PrepareAction::Failed`, return immediately with the failure (don't try to run the build).

### 3. Surface the report in the protocol

Extend the existing build-result type to include an optional `PrepareReport` so the daemon and hook can log it. Existing `BuildRecord` lives in `rch-common/src/types.rs`; add `prepare: Option<PrepareReport>` field.

### 4. Daemon-side: include prepare info in worker logs

Daemon logs should include `prepare.action` and `prepare.took_ms` so users can diagnose slow Bun builds (often dominated by npm install).

### 5. Worker-side cache cleanup

The `.rch_dep_fingerprint.json` and `node_modules/` live in the project's worker-side directory (`/tmp/rch/{project_id}/{hash}/`). Stable-paths from bd-5a5k mean these survive across builds with the same hash. When the project hash changes (different code), a new directory is created, leaving the old node_modules in the previous-hash directory; existing cleanup logic (also from bd-5a5k) keeps the newest and evicts old ones.

