#[test]
fn test_aggregation_correctness() {
    info!("TEST START: test_aggregation_correctness");
    let storage = TelemetryStorage::new_in_memory().unwrap();
    // Insert 60 samples for one hour with known values
    for i in 0..60 {
        let snapshot = TelemetrySnapshot {
            cpu: CpuMetrics { utilization_pct: 50.0 + i as f64, .. },
            timestamp: Utc::now() - Duration::minutes(60 - i),
            ..
        };
        storage.insert_telemetry(&snapshot).unwrap();
    }
    info!("INPUT: 60 samples with CPU 50-109%");
    storage.aggregate_old_telemetry().unwrap();
    let hourly = storage.get_hourly_telemetry("worker-1", ...).unwrap();
    info!("RESULT: Hourly avg = {}", hourly[0].cpu_percent_avg);
    // Average of 50..109 = 79.5
    assert!((hourly[0].cpu_percent_avg - 79.5).abs() < 0.1);
    info!("TEST PASS: test_aggregation_correctness");
}
