      phase: 'step',
      step,
      timestamp: new Date().toISOString(),
      ...data,
    }));
  },

  assertion: (testName: string, expected: unknown, actual: unknown, passed: boolean) => {
    console.log(JSON.stringify({
      level: passed ? 'INFO' : 'ERROR',
      test: testName,
      phase: 'assertion',
      expected,
      actual,
      passed,
      timestamp: new Date().toISOString(),
    }));
  },

  complete: (testName: string, status: 'PASSED' | 'FAILED', durationMs: number) => {
    console.log(JSON.stringify({
      level: status === 'PASSED' ? 'INFO' : 'ERROR',
      test: testName,
      phase: 'complete',
      status,
      duration_ms: durationMs,
      timestamp: new Date().toISOString(),
    }));
  },
};

