// web/e2e/utils/e2eLogger.ts
import { Page, TestInfo } from '@playwright/test';

export class E2ELogger {
  constructor(private testInfo: TestInfo, private page: Page) {}

  async log(level: string, message: string, data?: Record<string, unknown>) {
    const entry = {
      level,
      test: this.testInfo.title,
      file: this.testInfo.file,
      timestamp: new Date().toISOString(),
      url: this.page.url(),
      message,
      ...data,
    };

    console.log(JSON.stringify(entry));

    // Also attach to test report
    await this.testInfo.attach('log', {
      body: JSON.stringify(entry, null, 2),
      contentType: 'application/json',
    });
  }

  async screenshot(name: string) {
    const screenshot = await this.page.screenshot();
    await this.testInfo.attach(name, { body: screenshot, contentType: 'image/png' });
    await this.log('DEBUG', `Screenshot captured: ${name}`);
  }

  async networkLog(route: string, method: string, status: number, body?: unknown) {
    await this.log('DEBUG', 'Network request', {
      route,
      method,
      status,
      body_preview: JSON.stringify(body).slice(0, 500),
    });
  }
}

