## Implementation Details

### Alert State Machine
```rust
pub struct AlertManager {
    config: AlertConfig,
    active_alerts: HashMap<AlertKey, Alert>,
    last_sent: HashMap<AlertKey, DateTime<Utc>>,
}

impl AlertManager {
    pub fn check(&mut self, event: AlertEvent) {
        let key = event.key();

        // Check if alert is suppressed (duplicate within window)
        if let Some(last) = self.last_sent.get(&key) {
            if Utc::now() - last < self.config.suppress_duplicates {
                return;
            }
        }

        // Create and dispatch alert
        let alert = Alert::from_event(event);
        self.dispatch(alert);
        self.last_sent.insert(key, Utc::now());
    }

    async fn dispatch(&self, alert: Alert) {
        if self.config.desktop_notifications {
            self.send_desktop_notification(&alert);
        }

        if let Some(webhook) = &self.config.webhook {
            self.send_webhook(&alert, webhook).await;
        }
    }
}
```

