    let zstd_ok = zstd_result.as_ref().map(|o| o.exit_code == 0).unwrap_or(false);

    if !zstd_ok {
        tracing::warn!(worker = %worker.id, "zstd not found");
        issues.push(PreflightIssue {
            severity: Severity::Error,
            check: "zstd".to_string(),
