                worker.host
            )),
        });
    } else {
        tracing::debug!(worker = %worker.id, "zstd found");
    }

    tracing::info!(
        worker = %worker.id,
        rsync = %rsync_ok,
        zstd = %zstd_ok,
        "Tool availability check complete"
    );

    (rsync_ok, zstd_ok)
} else {
    // SSH failed, can't check tools
    (false, false)
};
\`\`\`

## Technical Details
- Use \`command -v\` (POSIX compliant, more portable than \`which\`)
- Exit code 0 = found, non-zero = not found
- These are CRITICAL dependencies - file transfer will fail without them
- Skip checks if SSH failed

