### Example: Version Comparison
```rust
proptest! {
    #[test]
    fn test_version_comparison_transitive(
        a in "[0-9]+\\.[0-9]+\\.[0-9]+",
        b in "[0-9]+\\.[0-9]+\\.[0-9]+",
        c in "[0-9]+\\.[0-9]+\\.[0-9]+",
    ) {
        if let (Ok(va), Ok(vb), Ok(vc)) = (
            Version::parse(&a),
            Version::parse(&b),
            Version::parse(&c),
        ) {
            // Transitivity: if a < b and b < c, then a < c
            if va < vb && vb < vc {
                prop_assert!(va < vc);
            }
        }
    }
}
