          metrics.timing.rsync_up, metrics.timing.remote_build,
          metrics.timing.rsync_down, metrics.timing.total);

    assert!(metrics.timing.rsync_up >= Duration::from_millis(10));
    assert!(metrics.timing.remote_build >= Duration::from_millis(20));
    assert!(metrics.success);
    info!("VERIFY: All timing phases recorded correctly");
    info!("TEST PASS: test_compilation_timer");
}

