    let mut agg = MetricsAggregator::new(100);

    info!("INPUT: Recording 5 metrics with varying speedups");
    for i in 1..=5 {
        let mut m = make_test_metrics();
        m.speedup = Some(i as f64);
        m.timing.total = Duration::from_secs(i as u64);
        agg.record(m);
    }

    let avg = agg.average_speedup().unwrap();
    let p95 = agg.p95_total_time().unwrap();

    info!("RESULT: average_speedup={}, p95_total={:?}", avg, p95);
    assert!((avg - 3.0).abs() < 0.01);  // Average of 1,2,3,4,5
