## Task
Implement the SSH connectivity validation step in run_preflight().

## What to Implement
Replace the hardcoded \`ssh_ok: true\` with actual SSH connection testing:

\`\`\`rust
// Before (stub):
ssh_ok: true,

// After (real):
let ssh_executor = SshExecutor::new(&worker, SSH_CONNECT_TIMEOUT);
let ssh_result = ssh_executor.check_connectivity().await;

let ssh_ok = match &ssh_result {
    Ok(connected) => *connected,
    Err(e) => {
        tracing::warn!(worker = %worker.id, error = %e, "SSH connectivity check failed");
        false
    }
};

// IMPORTANT: Populate issues vector on failure
if !ssh_ok {
    issues.push(PreflightIssue {
        severity: Severity::Error,
        check: "ssh".to_string(),
        message: match &ssh_result {
            Err(FleetError::ConnectionTimeout) => 
                format!("SSH connection to {} timed out after {}s", worker.host, SSH_CONNECT_TIMEOUT.as_secs()),
            Err(FleetError::AuthenticationFailed) =>
                format!("SSH authentication failed for {}@{}", worker.user, worker.host),
            Err(FleetError::HostUnreachable) =>
                format!("Host {} is unreachable", worker.host),
            Err(e) => format!("SSH connection failed: {}", e),
            Ok(false) => format!("SSH connection to {} returned false", worker.host),
            Ok(true) => unreachable!(),
        },
        remediation: Some(format!(
            "Check: 1) Host is reachable: ping {} 2) SSH service running 3) Key auth: ssh -i {} {}@{}",
            worker.host, worker.identity_file, worker.user, worker.host
        )),
    });
}
\`\`\`

