## What to Implement
```rust
const REMOTE_RCH_PATH: &str = "~/.local/bin/rch-wkr";

async fn query_single_worker(
    worker: &WorkerConfig,
    timeout: Duration,
) -> WorkerStatus {
    let worker_id = worker.id.0.clone();
    let ssh = SshExecutor::new(worker, timeout);
    let mut issues = Vec::new();

    // 1. Check reachability (SSH connectivity)
    tracing::debug!(worker = %worker_id, host = %worker.host, "Checking worker reachability");
    let reachable = match ssh.check_connectivity().await {
        Ok(connected) => connected,
        Err(e) => {
            tracing::warn!(worker = %worker_id, error = %e, "Worker unreachable");
            issues.push(format!("Connection failed: {}", e));
            false
        }
    };

    if !reachable {
        return WorkerStatus {
            worker_id,
            reachable: false,
            healthy: false,
            version: None,
            issues,
        };
    }

    // 2. Query rch-wkr version (indicates proper installation)
    // NOTE: Using hardcoded path since WorkerConfig doesn't have rch_wkr_path
    let version = match ssh.run_command(&format!("{} --version 2>/dev/null", REMOTE_RCH_PATH)).await {
        Ok(output) if output.exit_code == 0 => {
            // Parse "rch-wkr 1.0.0" -> "1.0.0"
            output.stdout.trim()
                .split_whitespace()
                .nth(1)
                .map(String::from)
        }
        Ok(_) => {
            issues.push("rch-wkr not installed or not executable".to_string());
            None
        }
        Err(e) => {
            issues.push(format!("Version check failed: {}", e));
            None
        }
    };

    // 3. Determine health based on:
    //    - reachable = true (already confirmed above)
    //    - rch-wkr installed (version is Some)
    //    - no critical issues
    let healthy = version.is_some() && issues.is_empty();

    tracing::info!(
        worker = %worker_id,
        reachable = %reachable,
        healthy = %healthy,
        version = ?version,
        issue_count = %issues.len(),
        "Worker status query complete"
    );

    WorkerStatus {
        worker_id,
        reachable,
        healthy,
        version,
        issues,
    }
}
```

